#include <cstdint>
#include <optional>
#include <vector>

inline std::uint32_t hash(std::uint32_t x)
{
    x ^= x >> 16; x *= 0x7feb352dU; x ^= x >> 15; x *= 0x846ca68bU; x ^= x >> 16;
    return x;
}

class IdTable
{
public:
    explicit IdTable(std::size_t slotCount) : m_slots(slotCount) {}

    bool insert(std::uint32_t key, int value)
    {
        const std::size_t n{ m_slots.size() };
        if (n == 0) return false;
        std::size_t i{ hash(key) % n };
        for (std::size_t tries{ 0 }; tries < n; ++tries)
        {
            Slot& s{ m_slots[i] };
            if (!s.used)
            {
                s = Slot{ true, key, value };
                ++m_count;
                return true;
            }
            if (s.key == key)
            {
                s.value = value;
                return true;
            }
            i = (i + 1) % n;
        }
        return false;
    }

    std::optional<int> find(std::uint32_t key) const
    {
        const std::size_t n{ m_slots.size() };
        if (n == 0) return std::nullopt;
        std::size_t i{ hash(key) % n };
        for (std::size_t tries{ 0 }; tries < n; ++tries)
        {
            const Slot& s{ m_slots[i] };
            if (!s.used) return std::nullopt;
            if (s.key == key) return s.value;
            i = (i + 1) % n;
        }
        return std::nullopt;
    }

    std::size_t size() const { return m_count; }

private:
    struct Slot { bool used{ false }; std::uint32_t key{ 0 }; int value{ 0 }; };
    std::vector<Slot> m_slots;
    std::size_t m_count{ 0 };
};

unitTests:
TEST("insert and find") { IdTable t{ 16 }; CHECK(t.insert(42, 7)); CHECK_EQ(*t.find(42), 7); CHECK_EQ(t.size(), std::size_t{ 1 }); }
TEST("missing keys") { IdTable t{ 16 }; t.insert(1, 1); CHECK(!t.find(2).has_value()); }
TEST("replacing a value keeps the size") { IdTable t{ 8 }; t.insert(5, 1); t.insert(5, 2); CHECK_EQ(*t.find(5), 2); CHECK_EQ(t.size(), std::size_t{ 1 }); }
TEST("many keys, with collisions")
{
    IdTable t{ 64 };
    for (std::uint32_t k{ 0 }; k < 50; ++k) CHECK(t.insert(k * 1000, static_cast<int>(k)));
    bool ok{ true };
    for (std::uint32_t k{ 0 }; k < 50; ++k) ok = ok && t.find(k * 1000) == static_cast<int>(k);
    CHECK(ok);
    CHECK_EQ(t.size(), std::size_t{ 50 });
}
TEST("a completely full table")
{
    IdTable t{ 4 };
    for (std::uint32_t k : { 10u, 20u, 30u, 40u }) CHECK(t.insert(k, 1));
    CHECK(!t.insert(50, 1));
    CHECK(t.insert(30, 9));                   // replacing still works when full
    CHECK_EQ(*t.find(30), 9);
    CHECK(!t.find(50).has_value());           // and a miss in a full table ends
}
TEST("probing wraps round")
{
    // Find two keys with the same home slot in a table of 4, the second home at the last slot.
    IdTable t{ 4 };
    std::uint32_t a{ 0 };
    while (hash(a) % 4 != 3) ++a;
    std::uint32_t b{ a + 1 };
    while (hash(b) % 4 != 3) ++b;
    t.insert(a, 1); t.insert(b, 2);           // b must wrap round to slot 0
    CHECK_EQ(*t.find(a), 1);
    CHECK_EQ(*t.find(b), 2);
}
TEST("a table with no slots") { IdTable t{ 0 }; CHECK(!t.insert(1, 1)); CHECK(!t.find(1).has_value()); }

